from typing import Generic, TypeVar, Union, Any

T = TypeVar('T')


class Option(Generic[T]):
    """Base class for Option types."""
    pass


class Some(Option[T]):
    """Represents an Option with a value."""

    def __init__(self, value: T) -> None:
        self.value = value

    def __repr__(self) -> str:
        return f"Some({self.value!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Some):
            return NotImplemented
        return self.value == other.value


class _NoneType(Option[T]):
    """Represents an Option with no value."""

    def __repr__(self) -> str:
        return "None"

    def __eq__(self, other: object) -> bool:
        return isinstance(other, _NoneType)


# Singleton instance for the None type
NONE: Option[Any] = _NoneType()


def safe_divide(numerator: Union[int, float], denominator: Union[int, float]) -> Union[Some[float], _NoneType]:
    """
    Performs safe division, returning Some(result) if the divisor is non-zero,
    or None if the divisor is zero.
    """
    if denominator == 0:
        return NONE
    return Some(float(numerator / denominator))


def main() -> None:
    """
    Tests the safe_divide function with various inputs and prints results.
    """
    test_cases = [
        (10, 2),
        (10, 0)
    ]

    for numerator, denominator in test_cases:
        result = safe_divide(numerator, denominator)
        if isinstance(result, Some):
            print(f"Result: {result.value}")
        elif isinstance(result, _NoneType):
            print("Error: Division by zero")


if __name__ == "__main__":
    main()

