import std/io (readFile, writeFile, println)
import std/json (decode, Json, JNull, JNumber, JString, JArray, JObject)

type Config = {
  app_name: string,
  version: string,
  port: int,
  features: List[string]
}

-- Default configuration returned on validation or parsing failure
let defaultConfig = {
  app_name: "DefaultApp",
  version: "0.0.0", -- Intentionally invalid version for fallback
  port: 0,          -- Intentionally invalid port for fallback
  features: []
}

-- Helper to count occurrences of a character in a string
func countChar(char_to_find: string, s: string) -> int {
  let len_s = _str_len(s) in
  letrec count_rec = \idx. \count.
    if idx >= len_s
    then count
    else
      let current_char = _str_slice(s, idx, idx + 1) in
      if _str_eq(current_char, char_to_find)
      then count_rec(idx + 1)(count + 1)
      else count_rec(idx + 1)(count)
  in
  count_rec(0)(0)
}

-- Helper to validate port range
func validatePort(port: int) -> bool =
  port >= 1024 && port <= 65535

-- Helper to validate version format (simple check: contains exactly two dots)
func validateVersion(ver: string) -> bool =
  countChar(".", ver) == 2

-- Helper: Find a key in a JSON object (adapted from prompt example)
func findKey(kvs: List[{key: string, value: Json}], target: string) -> Json {
  match kvs {
    [] => JNull,
    kv :: rest => if _str_eq(kv.key, target) then kv.value else findKey(rest, target)
  }
}

-- Helper to extract a field (Json value) from a Json object
func getField(json_obj: Json, field_name: string) -> Json {
  match json_obj {
    JObject(kvs) => findKey(kvs, field_name),
    _ => JNull -- Return JNull if not a JObject or key not found
  }
}

-- Helper to convert Json to string, returns empty string on type mismatch
func jsonToString(json: Json) -> string {
  match json {
    JString(s) => s,
    _ => ""
  }
}

-- Helper to convert Json to int, truncating float if necessary. Returns 0 on type mismatch.
func jsonToInt(json: Json) -> int {
  match json {
    JNumber(f) => floatToInt(f),
    _ => 0
  }
}

-- Helper to convert Json (JArray of JString) to List[string], returns empty list on mismatch
func jsonToStringList(json: Json) -> List[string] {
  match json {
    JArray(json_list) => {
      letrec convert_list_rec = \jsons.
        match jsons {
          [] => [],
          json_item :: rest => jsonToString(json_item) :: convert_list_rec(rest)
        }
      in
      convert_list_rec(json_list)
    },
    _ => []
  }
}

-- Helper to get list length (from prompt examples)
func length[a](xs: List[a]) -> int {
  match xs {
    [] => 0,
    _ :: rest => 1 + length(rest)
  }
}

-- Loads and validates configuration from a file. Returns defaultConfig on any error.
func loadConfig(filename: string) -> Config ! {FS} {
  let content = readFile(filename) in
  let json_decode_result = decode(content) in

  match json_decode_result {
    Ok(json_val) =>
      match json_val {
        JObject(kvs) => {
          let app_name = jsonToString(getField(json_val, "app_name")) in
          let version = jsonToString(getField(json_val, "version")) in
          let port = jsonToInt(getField(json_val, "port")) in
          let features = jsonToStringList(getField(json_val, "features")) in

          if validatePort(port)
          && validateVersion(version)
          && length(features) > 0
          then { app_name: app_name, version: version, port: port, features: features }
          else defaultConfig -- Return default if validation fails
        },
        _ => defaultConfig -- Not a JObject
      },
    Err(_) => defaultConfig -- JSON parse error
  }
}

export func main() -> () ! {IO, FS} {
  -- Create config file
  let config_content = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}" in
  let _ = writeFile("app_config.json", config_content) in

  -- Load and validate config
  let config = loadConfig("app_config.json") in

  -- Print result
  let numFeatures = length(config.features) in
  println("Loaded " ++ config.app_name ++ " v" ++ config.version ++ " on port " ++ show(config.port) ++ " with " ++ show(numFeatures) ++ " features")
}

