from typing import TypeVar, Generic, Callable, Any

T = TypeVar('T')

class Pure(Generic[T]):
    """Wrapper type for pure values - enforces that pure functions cannot call effectful ones"""
    def __init__(self, value: T):
        self._value = value

    def get(self) -> T:
        return self._value

class IO(Generic[T]):
    """Wrapper type for effectful computations - can call both pure and effectful functions"""
    def __init__(self, value: T):
        self._value = value

    def get(self) -> T:
        return self._value

# PURE functions - return Pure[T], cannot call effectful functions
def double(x: int) -> Pure[int]:
    """Pure function: doubles a number"""
    return Pure(x * 2)

def add(a: int, b: int) -> Pure[int]:
    """Pure function: adds two numbers"""
    return Pure(a + b)

# EFFECTFUL functions - return IO[T], can call pure and effectful functions
def printResult(label: str, value: int) -> IO[None]:
    """Effectful function: prints a labeled result"""
    print(f"{label}: {value}")
    return IO(None)

def compute_and_print() -> IO[None]:
    """Effectful function: computes using pure functions and prints result"""
    # Call pure functions and extract their values
    result1 = double(5).get()
    result2 = add(result1, 3).get()
    # Call effectful function
    printResult("Result", result2)
    return IO(None)

if __name__ == "__main__":
    compute_and_print()

