from functools import wraps
from typing import Callable, TypeVar, Any

# Effect tracking decorators
def io_effect(func: Callable) -> Callable:
    """Marks a function as having IO effects"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    wrapper._effects = {'io'}
    return wrapper

def io_fs_effect(func: Callable) -> Callable:
    """Marks a function as having IO and FS effects"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    wrapper._effects = {'io', 'fs'}
    return wrapper

# Pure function - no effect annotations
def computeSum(a: int, b: int) -> int:
    """Pure function with no side effects"""
    return a + b

# IO effect function
@io_effect
def printSum(a: int, b: int) -> None:
    """Function with IO effect"""
    result = computeSum(a, b)
    print(f"Sum: {result}")

# IO and FS effects function
@io_fs_effect
def logToFile(filename: str, message: str) -> None:
    """Function with IO and FS effects"""
    with open(filename, 'w') as f:
        f.write(message)

def main() -> None:
    """Main function demonstrating effect tracking"""
    # Call pure function
    result = computeSum(10, 20)

    # Call IO function
    printSum(10, 20)

    # Call IO+FS function
    logToFile("output.txt", "Sum was 30")

    # Print done message
    print("Done")

if __name__ == "__main__":
    main()

