import sys
from typing import TypeVar, Generic, Union, Any

T = TypeVar('T')
E = TypeVar('E')

class Ok(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def is_ok(self) -> bool:
        return True

    def is_err(self) -> bool:
        return False

    def __repr__(self) -> str:
        return f"Ok({self.value!r})"

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, Ok) and self.value == other.value

class Err(Generic[E]):
    def __init__(self, message: E):
        self.message = message

    def is_ok(self) -> bool:
        return False

    def is_err(self) -> bool:
        return True

    def __repr__(self) -> str:
        return f"Err({self.message!r})"

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, Err) and self.message == other.message

Result = Union[Ok[T], Err[str]]

def parse_int(s: str) -> Result[int]:
    try:
        value = int(s)
        return Ok(value)
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def _print_final_result(result: Result[Any]) -> None:
    if result.is_ok():
        print(f"Result: {result.value}")
    else:
        print(f"Error: {result.message}")

def main() -> None:
    # Test case 1: parse_int("10") then divide by 2 -> "Result: 5"
    parsed_res_1 = parse_int("10")
    final_res_1: Result[int]
    if parsed_res_1.is_ok():
        final_res_1 = divide_safe(parsed_res_1.value, 2)
    else:
        final_res_1 = parsed_res_1
    _print_final_result(final_res_1)

    # Test case 2: parse_int("10") then divide by 0 -> "Error: Division by zero"
    parsed_res_2 = parse_int("10")
    final_res_2: Result[int]
    if parsed_res_2.is_ok():
        final_res_2 = divide_safe(parsed_res_2.value, 0)
    else:
        final_res_2 = parsed_res_2
    _print_final_result(final_res_2)

    # Test case 3: parse_int("abc") -> "Error: Invalid integer"
    # This case implies the chain stops at the first error.
    parsed_res_3 = parse_int("abc")
    _print_final_result(parsed_res_3)

if __name__ == "__main__":
    main()

