def read_numbers_from_file(file_path: Path) -> List[int]:
    numbers: List[int] = []
    try:
        with file_path.open("r") as f:
            for line_num, line in enumerate(f, 1):
                stripped_line = line.strip()
                if not stripped_line:
                    continue
                try:
                    numbers.append(int(stripped_line))
                except ValueError:
                    raise ValueError(f"Line {line_num}: '{stripped_line}' is not a valid integer.")
    except FileNotFoundError:
        raise
    return numbers

def process_numbers(numbers: List[int]) -> List[int]:
    return [n * n for n in numbers]

def write_numbers_to_file(file_path: Path, numbers: List[int]) -> None:
    with file_path.open("w") as f:
        for number in numbers:
            f.write(f"{number}\n")

def main() -> None:
    input_file_path = Path("input.txt")
    output_file_path = Path("output.txt")

    if not input_file_path.exists():
        with input_file_path.open("w") as f:
            f.write("10\n")
            f.write("20\n")
            f.write("30\n")
            f.write("40\n")
        print(f"Created a sample input file: {input_file_path}")

