from dataclasses import dataclass
from typing import Union, List, Callable

@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Union[Leaf, Node]


def map_tree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """Apply function to all values in tree, returning new tree."""
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    else:
        return Node(
            map_tree(fn, tree.left),
            fn(tree.value),
            map_tree(fn, tree.right)
        )


def fold_tree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    """In-order fold over tree values."""
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    else:
        acc = fold_tree(fn, acc, tree.left)
        acc = fn(acc, tree.value)
        return fold_tree(fn, acc, tree.right)


def tree_to_list(tree: Tree) -> List[int]:
    """In-order traversal to list."""
    if isinstance(tree, Leaf):
        return [tree.value] if tree.value != 0 else []
    else:
        return tree_to_list(tree.left) + [tree.value] + tree_to_list(tree.right)


def tree_depth(tree: Tree) -> int:
    """Calculate tree depth."""
    if isinstance(tree, Leaf):
        return 1
    else:
        left_depth = tree_depth(tree.left)
        right_depth = tree_depth(tree.right)
        return 1 + max(left_depth, right_depth)


def main() -> None:
    """Test tree transformation pipeline."""
    tree = Node(
        Node(Leaf(1), 3, Leaf(0)),
        5,
        Node(Leaf(7), 8, Leaf(9))
    )

    original = [x for x in tree_to_list(tree) if x != 0]
    print(f"Original: {original}")

    doubled_tree = map_tree(lambda x: x * 2, tree)
    doubled = [x for x in tree_to_list(doubled_tree) if x != 0]
    print(f"Doubled: {doubled}")

    total = fold_tree(lambda a, b: a + b, 0, tree)
    print(f"Sum: {total}")

    depth = tree_depth(tree)
    print(f"Depth: {depth}")


if __name__ == "__main__":
    main()

